  @Nested
  @DisplayName("Authentication context")
  class Authentication {

    @Test
    @DisplayName("Should describe anonymous requests")
    void shouldDescribeAnonymous() {
      when(security.isAnonymous()).thenReturn(true);

      AuthenticationContext context = request().getAuthenticationContext();

      assertEquals(AuthenticationLevel.ANONYMOUS, context.getLevel());
      assertFalse(context.isSecureTransport());
      assertNull(context.getAuthenticationMethod());
      assertTrue(context.getAuthenticationAge().compareTo(Duration.ofSeconds(5)) < 0);
    }

    @ParameterizedTest(name = "{0} -> {1}")
    @CsvSource({"mfa, MFA", "otp, MFA", "webauthn, MFA", "pwd, PASSWORD_HTTPS",
        "password, PASSWORD_HTTPS", "remember_me, REMEMBERED", "remember-me, REMEMBERED",
        "kerberos, PASSWORD"})
    @DisplayName("Should derive the level from the authentication method")
    void shouldDeriveLevel(String amr, AuthenticationLevel expected) {
      authenticated();
      claims.put("amr", amr);

      AuthenticationContext context = request().getAuthenticationContext();

      assertEquals(expected, context.getLevel());
      assertEquals(amr, context.getAuthenticationMethod());
    }

    @Test
    @DisplayName("Should read methods from collections and arrays, plus session and flags")
    void shouldReadMethodCollections() {
      authenticated();
      headerValues.put("X-Forwarded-Proto", "https");
      claims.put("amr", Arrays.asList(null, "otp"));
      claims.put("typ", new String[] {null, "remember-me"});
      claims.put("act", Map.of("sub", "admin"));
      claims.put("sid", "session");

      AuthenticationContext context = request().getAuthenticationContext();

      assertEquals(AuthenticationLevel.MFA, context.getLevel());
      assertEquals("null otp", context.getAuthenticationMethod());
      assertTrue(context.isRememberMe());
      assertTrue(context.isImpersonated());
      assertTrue(context.isSecureTransport());
      assertEquals("session", context.getSessionId());
    }

    @Test
    @DisplayName("Should compare other claim types by their text")
    void shouldCompareOtherClaimTypes() {
      authenticated();
      claims.put("amr", new StringBuilder("MFA"));
      claims.put("typ", new String[] {"access"});

      AuthenticationContext context = request().getAuthenticationContext();

      assertTrue(context.isMfa());
      assertFalse(context.isRememberMe());
    }

    @ParameterizedTest(name = "{0}")
    @CsvSource({"1700000000, 2023-11-14T22:13:20Z",
        "2026-01-01T01:00:00+01:00, 2026-01-01T00:00:00Z",
        "2016-12-31T23:59:60Z, 2016-12-31T23:59:59Z"})
    @DisplayName("Should parse the auth time as epoch, zoned date or instant")
    void shouldParseAuthTime(String authTime, String expected) {
      authenticated();
      claims.put("auth_time", authTime);

      assertEquals(Instant.parse(expected),
          request().getAuthenticationContext().getAuthenticatedAt().toInstant());
    }

    @Test
    @DisplayName("Should use the issue time, or now, when there is no auth time")
    void shouldUseIssueTime() {
      authenticated();
      when(jwt.getClaim(Claims.iat)).thenReturn((Object) 1_600_000_000L);
      assertEquals(Instant.ofEpochSecond(1_600_000_000L),
          request().getAuthenticationContext().getAuthenticatedAt().toInstant());

      when(jwt.getClaim(Claims.iat)).thenReturn(null);
      assertTrue(Duration
          .between(request().getAuthenticationContext().getAuthenticatedAt(), ZonedDateTime.now())
          .compareTo(Duration.ofSeconds(5)) < 0);
    }

    @Test
    @DisplayName("Should fall back to now when the auth time cannot be parsed")
    void shouldFallBackToNowForInvalidAuthTime() {
      authenticated();
      claims.put("auth_time", "yesterday");

      assertTrue(Duration
          .between(request().getAuthenticationContext().getAuthenticatedAt(), ZonedDateTime.now())
          .compareTo(Duration.ofSeconds(5)) < 0);
    }

    @Test
    @DisplayName("Should build the operation context from the request")
    void shouldBuildInteraction() {
      authenticated();
      claims.put("amr", "pwd");

      OperationContext context = request().interaction();

      assertEquals("u-1", context.getActor().getUid());
      assertEquals(InvocationChannel.API, context.getSource().getChannel());
      assertEquals(AuthenticationLevel.PASSWORD_HTTPS, context.getAuthentication().getLevel());
      verify(magicLinks, times(1)).extractToken(any());
    }
  }
